select f.follow_user_id userId, p2.uptime `time`, p2.lat `lat`, p2.lng `lng`, d2.nickname `nickname`, d2.avatar `avatar`, d2.avatar_check_status `avatarCheckStatus` from corgi_user_follow f left join corgi_user_position p2 on f.follow_user_id = p2.user_id left join corgi_user_detail d2 on f.follow_user_id = d2.user_id where f.user_id = #{userId} and is_deleted = '0'
and d2.nickname like concat('%',#{name},'%')
order by `time` desc limit #{start}, #{size}

